def reverse_string(s: str, start_index: int | None = None, end_index: int | None = None) -> str | None:
    if not isinstance(s, str):
        return None
    if not s:
        return ""

    if start_index is None:
        start_index = 0
    if end_index is None:
        end_index = len(s)

    sub_string_to_reverse: str | None = s[start_index:end_index]
    if sub_string_to_reverse is None:
        return None

    chars: list[str | None] = list(sub_string_to_reverse)
    left: int | None = 0
    right: int | None = len(chars) - 1

    while left < right:
        if chars[left] is not None and chars[right] is not None:
            chars[left], chars[right] = chars[right], chars[left]
        left += 1
        right -= 1

    result: str | None = "".join(char for char in chars if char is not None)
    return result

