def calculate_factorial(n: int) -> int | None:
    """
    Computes the factorial of a non-negative integer n.

    Args:
        n: The non-negative integer for which to compute the factorial.

    Returns:
        The factorial of n, or None if n is negative.
    """
    if n < 0:
        return None  # n is negative, factorial is undefined

    result: int | None = 1
    i: int | None = 1
    while i <= n:
        if result is None:
            return None # Should not happen with valid input
        result *= i
        if i is not None:
            i += 1
        else:
            return None # Should not happen
    return result

def main(test_value: int | None = 5) -> str | None:
    if test_value is None:
        return "Input value cannot be None."

    factorial_result: int | None = calculate_factorial(test_value)

    if factorial_result is not None:
        return f"The factorial of {test_value} is {factorial_result}."
    else:
        return f"Factorial is not defined for {test_value}."

if __name__ == "__main__":
    print(main(5))
    print(main(0))
    print(main(3))
    print(main(-1))
    print(main(None))

