def find_max(numbers: list[int],
             initial_max: int | None = None,
             start_index: int | None = 0,
             end_index: int | None = None) -> int | None:
    if not numbers:
        return initial_max

    current_max: int | None = initial_max

    effective_start = start_index if start_index is not None else 0
    effective_end = end_index if end_index is not None else len(numbers)

    for i in range(effective_start, effective_end):
        num: int | None = numbers[i]
        if num is not None:
            if current_max is None or num > current_max:
                current_max = num

    return current_max

