def simple_calculator(num1: float, operator: str, num2: float) -> float | str:
    """
    Performs basic arithmetic operations (+, -, *, /) on two numbers.
    Handles division by zero by returning 'Error'.
    """
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return 'Error'
        return num1 / num2
    else:
        return 'Error'

def calculate_expression(expression: str | None) -> float | str:
    """
    Parses a simple string expression and calculates the result.
    Example: "10 + 5" -> 15.
    """
    if expression is None:
        return 'Error'
    parts: list[str] | None = expression.split()
    if len(parts) != 3:
        return 'Error'

    try:
        n1: float | None = float(parts[0])
        op: str = parts[1]
        n2: float | None = float(parts[2])
    except ValueError:
        return 'Error'

    if n1 is None or n2 is None:
        return 'Error'

    return simple_calculator(n1, op, n2)

def get_user_input(prompt: str) -> str | None:
    """
    Gets input from the user.
    """
    user_input: str | None = input(prompt)
    if not user_input:
        return None
    return user_input.strip()

def run_calculator_app() -> None:
    """
    Runs a simple calculator application loop.
    """
    while True:
        expr: str | None = get_user_input("Enter expression (e.g., '10 + 5') or 'quit': ")
        if expr is None or expr.lower() == 'quit':
            break
        result: float | str = calculate_expression(expr)
        print(f"Result: {result}")

if __name__ == '__main__':
    run_calculator_app()

