import math

def is_prime(n: int) -> bool | None:
    if n is None or not isinstance(n, int):
        return None
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i: int | None = 5
    while i * i <= n:
        if i is None:
            return None # Should not happen with current logic
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_primes_in_range(start: int, end: int | None) -> list[int] | None:
    if end is None:
        end = start + 10 # Default range if end is not provided
    if not isinstance(start, int) or not isinstance(end, int) or start < 0 or end < 0:
        return None
    primes: list[int] = []
    current_num: int | None = max(2, start) # Start checking from at least 2
    while current_num <= end:
        if current_num is None:
            return None
        if is_prime(current_num):
            primes.append(current_num)
        current_num += 1
    return primes

def get_prime_count(limit: int | None) -> int | None:
    if limit is None or not isinstance(limit, int) or limit < 0:
        return None
    primes_found: list[int] | None = find_primes_in_range(0, limit)
    if primes_found is None:
        return None
    return len(primes_found)

