def caesar_cipher_encrypt(text: str, shift: int | None) -> str:
    """
    Encrypts a string using the Caesar cipher.
    """
    if shift is None:
        return text

    encrypted_text: list[str] = []
    for char in text:
        if 'a' <= char <= 'z':
            start: int | None = ord('a')
            encrypted_char: str = chr((ord(char) - start + shift) % 26 + start) if start is not None else char
        elif 'A' <= char <= 'Z':
            start: int | None = ord('A')
            encrypted_char: str = chr((ord(char) - start + shift) % 26 + start) if start is not None else char
        else:
            encrypted_char: str = char
        encrypted_text.append(encrypted_char)
    return "".join(encrypted_text)

def main(input_text: str | None = None, input_shift: int | None = None) -> str | None:
    """
    Example usage of the caesar_cipher_encrypt function.
    """
    if input_text is None:
        input_text = 'Hello, World!'
    if input_shift is None:
        input_shift = 3

    result: str | None = caesar_cipher_encrypt(input_text, input_shift)
    return result

if __name__ == "__main__":
    encrypted_message: str | None = main('xyz', 3)
