def guess_number(secret_number: int | None, guess: int | None) -> str | None:
    if secret_number is None or guess is None:
        return "Invalid input: secret_number or guess cannot be None."

    if guess < secret_number:
        return "Too low"
    elif guess > secret_number:
        return "Too high"
    else:
        return "Correct!"

def play_game(target: int | None = None, attempts: int | None = 3) -> str | None:
    if target is None:
        import random
        target = random.randint(1, 10)

    if attempts is None or attempts < 1:
        return "Invalid attempts count."

    for i in range(attempts):
        user_guess_str: str | None = input(f"Attempt {i+1}/{attempts}. Enter your guess (1-10): ")

        user_guess: int | None = None
        try:
            if user_guess_str is not None:
                user_guess = int(user_guess_str)
        except ValueError:
            print("Invalid input. Please enter a number.")
            continue

        result: str | None = guess_number(target, user_guess)
        print(result)

        if result == "Correct!":
            return "Congratulations! You guessed the number."

    return f"Sorry, you ran out of attempts. The number was {target}."

