def calculate_bmi(weight_kg: float | int, height_m: float | int) -> float | None:
    """
    Calculates the Body Mass Index (BMI) given weight in kilograms and height in meters.

    Args:
        weight_kg: The weight of the person in kilograms.
        height_m: The height of the person in meters.

    Returns:
        The calculated BMI as a float, or None if invalid input is provided.
    """
    if not isinstance(weight_kg, (float, int)) or not isinstance(height_m, (float, int)):
        return None
    if weight_kg <= 0 or height_m <= 0:
        return None
    try:
        bmi_value: float = weight_kg / (height_m ** 2)
        return round(bmi_value, 2)
    except ZeroDivisionError:
        return None
    except TypeError:
        return None

def get_bmi_category(bmi: float | None, age: int | None = None) -> str | None:
    """
    Determines the BMI category based on the BMI value.

    Args:
        bmi: The calculated BMI value.
        age: Optional age of the person (not used in this simplified categorization).

    Returns:
        A string representing the BMI category, or None if BMI is invalid.
    """
    if bmi is None:
        return None
    if bmi < 18.5:
        return "Underweight"
    elif 18.5 <= bmi < 24.9:
        return "Normal weight"
    elif 25 <= bmi < 29.9:
        return "Overweight"
    elif bmi >= 30:
        return "Obese"
    else:
        return None

def format_bmi_result(bmi: float | None, unit: str | None = "kg/m^2") -> str | None:
    """
    Formats the BMI result into a human-readable string.

    Args:
        bmi: The calculated BMI value.
        unit: Optional unit string for the BMI.

    Returns:
        A formatted string, or None if BMI is invalid.
    """
    if bmi is None:
        return "Invalid input for BMI calculation."
    if unit is None:
        unit = "units"
    category: str | None = get_bmi_category(bmi)
    if category is None:
        return f"BMI: {bmi:.2f} {unit} (Category unknown)"
    return f"BMI: {bmi:.2f} {unit} ({category})"

