def simulate_queue(operations: list[tuple[str, int | None]]) -> list[int | None]:
    """
    Simulates a queue's operations and returns its final state.
    """
    queue: list[int | None] = []
    for operation, item in operations:
        if operation == 'enqueue':
            if item is not None:
                queue.append(item)
        elif operation == 'dequeue':
            if queue:
                queue.pop(0)
    return queue

