def has_unique_chars(s: str | None) -> bool | None:
    """
    Checks if all characters in a string are unique.

    Args:
        s: The input string. Can be None.

    Returns:
        True if all characters are unique, False otherwise.
        None if the input string is None.
    """
    if s is None:
        return None
    if not s:
        return True
    seen_chars: set[str] = set()
    for char in s:
        if char in seen_chars:
            return False
        seen_chars.add(char)
    return True

def find_first_unique_char_index(s: str | None, start_index: int | None = 0) -> int | None:
    """
    Finds the index of the first unique character in a string.

    Args:
        s: The input string. Can be None.
        start_index: The index to start searching from. Defaults to 0. Can be None.

    Returns:
        The index of the first unique character, or -1 if no unique character is found.
        None if the input string or start_index is None.
    """
    if s is None or start_index is None:
        return None
    if not s:
        return -1
    char_counts: dict[str, int] = {}
    for i, char in enumerate(s):
        if i < start_index:
            continue
        char_counts[char] = char_counts.get(char, 0) + 1

    for i, char in enumerate(s):
        if i < start_index:
            continue
        if char_counts[char] == 1:
            return i
    return -1

