def portfolio_value(stocks: dict[str, int | None], prices: dict[str, float | None]) -> float:
    """Calculates the total value of a stock portfolio."""
    total_value: float = 0.0
    for ticker, quantity in stocks.items():
        if quantity is None or quantity < 0:
            continue
        price: float | None = prices.get(ticker)
        if price is None or price < 0:
            continue
        total_value += quantity * price
    return total_value

