def binary_to_decimal(binary_string: str) -> int | None:
    if not isinstance(binary_string, str):
        return None

    decimal_value: int = 0
    power: int = 0

    for digit_char in reversed(binary_string):
        if digit_char == '1':
            decimal_value += 2 ** power
        elif digit_char != '0':
            return None # Invalid character
        power += 1

    return decimal_value

