from typing import Optional

def is_valid_parentheses(s: str) -> bool:
    stack: list[str] = []
    mapping: dict[str, str] = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            top_element: Optional[str] = stack.pop() if stack else None
            if top_element != mapping[char]:
                return False
        else:
            stack.append(char)

    return not stack

