import math

def calculate_std_dev(numbers: list[float]) -> float | None:
    """
    Calculates the sample standard deviation of a list of numbers.
    Assumes at least two numbers are provided.
    """
    if len(numbers) < 2:
        return None

    n: int = len(numbers)
    mean: float = sum(numbers) / n
    variance: float = sum((x - mean) ** 2 for x in numbers) / (n - 1)
    return math.sqrt(variance)

