def roman_to_int(roman_numeral: str) -> int | None:
    """
    Converts a Roman numeral string to its integer equivalent.
    Assumes valid Roman numerals.
    """
    roman_map: dict[str, int] = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total: int | None = 0
    prev_value: int | None = 0

    for char in reversed(roman_numeral):
        current_value: int | None = roman_map.get(char)
        if current_value is None:
            return None  # Should not happen with valid input

        if prev_value is not None and current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    return total

