def has_conflict(schedule: list[tuple[int, int]], new_event_start: int, new_event_end: int | None) -> bool | None:
    if not schedule and new_event_end is None:
        return None

    if new_event_start is None or new_event_end is None:
        return None

    for existing_start, existing_end in schedule:
        if existing_start is None or existing_end is None:
            continue
        if max(existing_start, new_event_start) < min(existing_end, new_event_end):
            return True
    return False

def add_event(schedule: list[tuple[int, int | None]], start: int, end: int) -> list[tuple[int, int]]:
    if start is None or end is None:
        return schedule
    if has_conflict(schedule, start, end):
        return schedule
    schedule.append((start, end))
    schedule.sort(key=lambda x: x[0])
    return schedule

def get_next_available_slot(schedule: list[tuple[int | None, int]], min_duration: int = 1) -> tuple[int, int] | None:
    if not schedule:
        return (0, min_duration)

    last_end: int | None = 0
    for existing_start, existing_end in schedule:
        if existing_start is None or existing_end is None:
            continue
        if existing_start - last_end >= min_duration:
            return (last_end, last_end + min_duration)
        last_end = max(last_end, existing_end)

    if last_end is not None:
        return (last_end, last_end + min_duration)
    return None

