def calculate_median(numbers: list[int | float]) -> float | None:
    """Calculates the median of a list of numbers."""
    if not numbers:
        return None

    sorted_numbers: list[int | float] = sorted(numbers)
    n: int = len(sorted_numbers)
    middle_index: int | float = n // 2

    if n % 2 == 1:
        return float(sorted_numbers[int(middle_index)])
    else:
        lower_middle: float | int = sorted_numbers[int(middle_index - 1)]
        upper_middle: float | int = sorted_numbers[int(middle_index)]
