def decrypt_caesar(text: str, shift: int) -> str:
    """Decrypts a message encrypted with a Caesar cipher."""
    decrypted_chars: list[str] = []
    for char in text:
        if 'a' <= char <= 'z':
            start_code: int | None = ord('a')
            shifted_code: int = ord(char) - shift
            decrypted_code: int = (shifted_code - start_code) % 26 + start_code
            decrypted_chars.append(chr(decrypted_code))
        else:
            decrypted_chars.append(char)
    return "".join(decrypted_chars)

