import re

def is_valid_url(url: str | None) -> bool | None:
    """
    Checks if a given string is a valid URL.

    A simple check involves starting with 'http://' or 'https://'
    and containing at least one '.' after the scheme.
    """
    if url is None:
        return False

    scheme_match: re.Match[str] | None = re.match(r"^(http|https)://", url)
    if not scheme_match:
        return False

    scheme_end_index: int | None = scheme_match.end()
    if scheme_end_index is None:
        return False

    domain_part: str | None = url[scheme_end_index:]
    if domain_part is None:
        return False

    return "." in domain_part and bool(domain_part)

def get_url_domain(url: str | None) -> str | None:
    """Extracts the domain from a valid URL."""
    if not is_valid_url(url) or url is None:
        return None

    scheme_match: re.Match[str] | None = re.match(r"^(http|https)://", url)
    if scheme_match is None:
        return None

    scheme_end: int | None = scheme_match.end()
    if scheme_end is None:
        return None

    domain_start: int | None = scheme_end
    domain_end: int | None = url.find('/', domain_start)

    if domain_end == -1:
        return url[domain_start:]
    else:
        return url[domain_start:domain_end]

