def harmonic_mean(numbers: list[float], default_value: float | None = None) -> float | None:
    if not numbers:
        return default_value

    reciprocal_sum: float = 0.0
    for num in numbers:
        if num <= 0:
            raise ValueError("All numbers must be positive")
        reciprocal_sum += 1 / num

