import re

def count_words(text: str, delimiter: str | None = None, strip_whitespace: bool | None = True) -> int:
    """
    Counts the number of words in a given string.

    Args:
        text: The input string.
        delimiter: The character(s) to split the string by. Defaults to whitespace.
        strip_whitespace: Whether to strip leading/trailing whitespace from each potential word.

    Returns:
        The number of words in the string.
    """
    if not text:
        return 0

    if strip_whitespace:
        text = text.strip()

    if delimiter is None:
        words = re.split(r'\s+', text)
    else:
        words = text.split(delimiter)

    valid_words: list[str] = [word for word in words if word]
    return len(valid_words)

def analyze_text(input_text: str, min_len: int | None = 1, max_len: int | None = None) -> dict[str, int | None]:
    word_count_result: int = count_words(input_text, strip_whitespace=True)
    longest_word_len: int | None = None
    if word_count_result > 0:
        words = re.split(r'\s+', input_text.strip())
        filtered_words = [w for w in words if len(w) >= (min_len or 0) and (max_len is None or len(w) <= max_len)]
        if filtered_words:
            longest_word_len = max(len(w) for w in filtered_words)

    result_dict: dict[str, int | None] = {
        "total_words": word_count_result,
        "longest_word_length": longest_word_len
    }
    return result_dict

