def flatten_dict(nested_dict: dict, separator: str | None = '_') -> dict:
    flattened: dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                new_key: str | None = f"{key}{separator}{sub_key}" if separator else f"{key}{sub_key}"
                if new_key is not None:
                    flattened[new_key] = sub_value
        else:
            flattened[key] = value
    return flattened

