def decimal_to_hex(decimal_num: int | None) -> str:
    """
    Converts a decimal integer to its hexadecimal string representation.
    """
    if decimal_num is None:
        return ""
    if decimal_num == 0:
        return "0"

    hex_chars: list[str] = []

    while decimal_num > 0:
        remainder: int | None = decimal_num % 16
        if remainder < 10:
            hex_chars.append(str(remainder))
        else:
            hex_chars.append(chr(ord('A') + remainder - 10))
        decimal_num //= 16

    return "".join(reversed(hex_chars))

def example_usage(value1: int | None, value2: int | None) -> None:
    """
    Demonstrates the usage of the decimal_to_hex function.
    """
    result1: str = decimal_to_hex(value1)
    print(f"Decimal {value1} is Hex {result1}")

    result2: str = decimal_to_hex(value2)
    print(f"Decimal {value2} is Hex {result2}")

if __name__ == "__main__":
    example_usage(255, 10)
    example_usage(None, 0)

