    """Groups anagrams together from a list of words."""
    anagram_map: Dict[str, List[str]] = defaultdict(list)

    for word_item in words:
        sorted_word: str = "".join(sorted(word_item))
        anagram_map[sorted_word].append(word_item)

    return list(anagram_map.values())

