    min_size: Union[int, None] = 1,
    max_size: Union[int, None] = None
) -> Union[bool, None]:
    """Checks if any group is empty, optionally considering group size."""
    if not groups:
        return True # Consider no groups as "containing" no empty groups.

    for group in groups:
        if not group and min_size is not None:
            return True # An empty group exists
        if min_size is not None and len(group) < min_size:
            return True # Group is smaller than min_size
        if max_size is not None and len(group) > max_size:
