def is_sorted(numbers: list[int | float], reverse: bool | None = False) -> bool:
    """
    Checks if a list of numbers is sorted in ascending or descending order.

    Args:
        numbers: The list of numbers to check.
        reverse: If True, checks for descending order. Defaults to False (ascending).

    Returns:
        True if the list is sorted, False otherwise.
    """
    if not numbers:
        return True

    for i in range(len(numbers) - 1):
        current_num: int | float = numbers[i]
        next_num: int | float = numbers[i + 1]

        if reverse:
            if current_num < next_num:
                return False
        else:
            if current_num > next_num:
                return False
    return True

def get_first_element(data: list[int | float] | None) -> int | float | None:
