    if data:
        return data[0]
    return None

def find_min_if_sorted(numbers: list[int | float] | None, allow_empty: bool | None = True) -> int | float | None:
    """
    Finds the minimum element of a sorted list. Returns None if the list is empty
    or not sorted.
    """
    if numbers is None or (not allow_empty and not numbers):
        return None
    if not numbers:
        return None
    if is_sorted(numbers):
        return numbers[0]
    return None

