def get_item_quantity(inventory: dict[str, int], item_name: str) -> int:
    """
    Checks the quantity of a specific item in the inventory.

    Args:
        inventory: A dictionary where keys are item names (str) and values are quantities (int).
        item_name: The name of the item (str) to check.

    Returns:
        The quantity of the item (int) if found, otherwise 0.
    """
    return inventory.get(item_name, 0)

def update_item_quantity(inventory: dict[str, int], item_name: str, new_quantity: int | None = None) -> dict[str, int]:
    if new_quantity is None or new_quantity < 0:
        if item_name in inventory:
            del inventory[item_name]
    else:
        inventory[item_name] = new_quantity
    return inventory

def check_inventory_status(inventory: dict[str, int], item_name: str, threshold: int | None = None) -> str | None:
    quantity = get_item_quantity(inventory, item_name)
    if quantity == 0:
        return f"{item_name} is out of stock."
    if threshold is not None and quantity < threshold:
        return f"{item_name} is low (quantity: {quantity})."
    return None

