def has_overlap(task1_start: int, task1_end: int, task2_start: int | None, task2_end: int | None) -> bool:
    """
    Detects if two tasks, each with a start and end time, overlap.
    Times are integers representing hours in a 24-hour format.
    """
    if task2_start is None or task2_end is None:
        return False

    # Check for invalid time ranges (end before start)
    if task1_start >= task1_end or task2_start >= task2_end:
        return False

    # Check for overlap
    # Task 1 starts before Task 2 ends AND Task 2 starts before Task 1 ends
    return task1_start < task2_end and task2_start < task1_end

def find_first_overlap(tasks: list[tuple[int, int]], new_task_start: int, new_task_end: int | None) -> int | None:
    """
    Finds the index of the first task in a list that overlaps with a new task.
    Returns the index if an overlap is found, otherwise None.
    """
    if new_task_end is None:
        return None

    for i, (task_start, task_end) in enumerate(tasks):
        if has_overlap(task_start, task_end, new_task_start, new_task_end):
            return i
    return None

def is_schedule_valid(schedule: list[tuple[int, int]], max_tasks: int | None = None) -> bool:
    """
    Checks if a schedule is valid (no overlapping tasks within itself)
    and optionally if it exceeds a maximum number of tasks.
    """
    if max_tasks is None:
        max_tasks = float('inf')
    if len(schedule) > max_tasks:
        return False

    for i in range(len(schedule)):
        for j in range(i + 1, len(schedule)):
            t1_start, t1_end = schedule[i]
            t2_start, t2_end = schedule[j]
            if has_overlap(t1_start, t1_end, t2_start, t2_end):
                return False
    return True

