def hex_to_decimal(hex_string: str, default_value: int | None = None) -> int:
    """
    Converts a hexadecimal string to its decimal integer equivalent.
    """
    decimal_value: int = 0
    power: int = 0

    for digit in reversed(hex_string):
        if '0' <= digit <= '9':
            val: int = int(digit)
        elif 'A' <= digit <= 'F':
            val = ord(digit) - ord('A') + 10
        elif 'a' <= digit <= 'f':
            val = ord(digit) - ord('a') + 10
        else:
            if default_value is not None:
                return default_value
            raise ValueError(f"Invalid hex character: {digit}")

        decimal_value += val * (16 ** power)
        power += 1

    return decimal_value

def display_result(hex_input: str, result: int | None = None) -> str | None:
    if result is None:
        return f"Conversion for '{hex_input}' failed."
    return f"The decimal equivalent of '{hex_input}' is {result}."

def process_hex_list(hex_list: list[str], fallback_return: int | None = 0) -> list[int | None]:
    results: list[int | None] = []
    for hex_val in hex_list:
        try:
            results.append(hex_to_decimal(hex_val))
        except ValueError:
            results.append(fallback_return)
    return results

if __name__ == '__main__':
    print(hex_to_decimal('A'))
    print(hex_to_decimal('1A'))
    print(hex_to_decimal('FF'))
    print(display_result('C', hex_to_decimal('C')))
    print(display_result('G', None))

    test_list = ['1', 'B', 'Z', '10']
    processed = process_hex_list(test_list, fallback_return=None)
    print(processed)

