def is_valid_luhn(card_number: str) -> bool | None:
    """
    Checks a credit card number using a simplified Luhn algorithm.
    """
    total_sum: int | None = 0
    is_second_digit: bool | None = False

    for digit_char in reversed(card_number):
        digit: int | None = int(digit_char)
        current_digit: int | None = digit

        if is_second_digit:
            current_digit *= 2
            if current_digit > 9:
                current_digit -= 9

        if total_sum is not None:
            total_sum += current_digit
        else:
            return None # Handle unexpected None in total_sum

        is_second_digit = not is_second_digit

    if total_sum is not None:
        return total_sum % 10 == 0
    return False # Default return if total_sum is None for some reason

