def calculate_bmi(weight_kg: float, height_m: float, precision: int | None = 2) -> float | None:
    if height_m <= 0 or weight_kg <= 0:
        return None
    bmi = weight_kg / (height_m * height_m)
    if precision is not None and precision >= 0:
        return round(bmi, precision)
    return bmi

def get_bmi_category(bmi_value: float | None) -> str | None:
    if bmi_value is None:
        return None
    if bmi_value < 18.5:
        return "Underweight"
    elif 18.5 <= bmi_value < 24.9:
        return "Normal weight"
    elif 25 <= bmi_value < 29.9:
        return "Overweight"
    else:
        return "Obesity"

def analyze_bmi(weight: float | None, height: float | None, round_to: int | None = 2) -> dict[str, float | str | None]:
    if weight is None or height is None:
        return {"bmi": None, "category": None}
    calculated_bmi = calculate_bmi(weight, height, round_to)
    category = get_bmi_category(calculated_bmi)
    return {"bmi": calculated_bmi, "category": category}

