def calculate_compound_interest(principal: float, rate: float, compounding_frequency: int, time_years: int) -> float:
    """
    Calculates the compound interest for a given principal amount.

    Args:
        principal (float): The initial principal amount.
        rate (float): The annual interest rate (as a decimal).
        compounding_frequency (int): The number of times interest is compounded per year.
        time_years (int): The number of years the money is invested or borrowed for.

    Returns:
        float: The total amount after compounding.
    """
    amount = principal * (1 + rate / compounding_frequency) ** (compounding_frequency * time_years)
    return amount

def _validate_inputs(principal: float | None, rate: float | None, compounding_frequency: int | None, time_years: int | None) -> tuple[float, float, int, int]:
    if principal is None or principal < 0:
        raise ValueError("Principal must be a non-negative number.")
    if rate is None or not (0 <= rate <= 1):
        raise ValueError("Rate must be between 0 and 1.")
    if compounding_frequency is None or compounding_frequency < 1:
        raise ValueError("Compounding frequency must be at least 1.")
    if time_years is None or time_years < 0:
        raise ValueError("Time in years must be a non-negative integer.")
    return principal, rate, compounding_frequency, time_years

def calculate_compound_interest_robust(principal: float | None, rate: float | None, compounding_frequency: int | None, time_years: int | None) -> float:
    p, r, n, t = _validate_inputs(principal, rate, compounding_frequency, time_years)
    return calculate_compound_interest(p, r, n, t)

