    if value is None:
        return False
    return min_val <= value <= max_val

def has_leading_zero(octet_str: str) -> bool | None:
    """Checks for leading zeros in an octet string."""
    if not octet_str:
        return None
    return len(octet_str) > 1 and octet_str[0] == '0'

