def get_divisors(number: int, include_self: bool = False) -> list[int]:
    divisors: list[int] = []
    for i in range(1, int(number**0.5) + 1):
        if number % i == 0:
            divisors.append(i)
            if i * i != number and i != 1:
                divisors.append(number // i)
    if include_self and number not in divisors:
        divisors.append(number)
    return sorted(divisors)

def is_perfect_number(number: int, debug_output: bool = False | None) -> bool:
    if number <= 0:
        return False
    proper_divisors: list[int] = get_divisors(number)
    if 1 in proper_divisors:
        proper_divisors.remove(1) # Remove the number itself if present (from the case number = 1)

    if debug_output:
        print(f"Proper divisors of {number}: {proper_divisors}")

    sum_divisors: int = sum(proper_divisors)

    if debug_output:
        print(f"Sum of proper divisors: {sum_divisors}")

    return sum_divisors == number

