    result = is_perfect_number(num_to_check, debug_output=verbose)
    if result == expected_result:
        if verbose:
            print(f"Test for {num_to_check} passed.")
        return None
    else:
        return f"Test for {num_to_check} failed. Expected {expected_result}, got {result}."

