def is_prime(num: int, limit: int | None = None) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num and (limit is None or i <= limit):
        if num % i == 0:
            return False
        i += 2
    return True

def generate_primes(n: int, start_from: int | None = None, step: int | None = None, max_primes: int | None = None, verbose: bool | None = False) -> list[int]:
    primes = []
    current_num = start_from if start_from is not None else 2
    actual_step = step if step is not None else 1
    while current_num <= n:
        if is_prime(current_num):
            primes.append(current_num)
            if max_primes is not None and len(primes) >= max_primes:
                break
            if verbose:
                print(f"Found prime: {current_num}")
        current_num += actual_step
    return primes

