def convert_length(value: float, from_unit: str, to_unit: str) -> float | None:
    """Converts a length value between meters and feet."""
    METERS_TO_FEET_FACTOR: float = 3.28084

    if from_unit == 'm' and to_unit == 'ft':
        result: float | None = value * METERS_TO_FEET_FACTOR
    elif from_unit == 'ft' and to_unit == 'm':
        result = value / METERS_TO_FEET_FACTOR
    elif from_unit == to_unit:
        result = value
    else:
        result = None  # Indicate invalid units

    return result

def get_user_input(prompt: str) -> str | None:
    """Gets string input from the user."""
    user_input: str | None = input(prompt)
    return user_input if user_input else None

def main() -> None:
    val_str: str | None = get_user_input("Enter value: ")
    if val_str is None:
        print("Value cannot be empty.")
        return
    try:
        value: float = float(val_str)
    except ValueError:
        print("Invalid value. Please enter a number.")
        return

    from_u: str | None = get_user_input("Convert from (m/ft): ")
    to_u: str | None = get_user_input("Convert to (m/ft): ")

    if from_u is None or to_u is None:
        print("Units cannot be empty.")
        return
    if from_u not in ['m', 'ft'] or to_u not in ['m', 'ft']:
        print("Invalid unit. Use 'm' or 'ft'.")
        return

    converted_value: float | None = convert_length(value, from_u, to_u)

    if converted_value is not None:
        print(f"Converted value: {converted_value:.4f} {to_u}")
    else:
        print("Conversion not possible due to invalid unit combination.")

if __name__ == "__main__":
    main()

