def has_all_unique_chars(s: str, case_sensitive: bool | None = True) -> bool:
    """
    Determines if a string contains all unique characters.

    Args:
        s: The input string.
        case_sensitive: Whether character comparison should be case-sensitive. Defaults to True.

    Returns:
        True if all characters are unique, False otherwise.
    """
    if s is None:
        return True

    seen_chars: set[str] = set()
    for char_index, char in enumerate(s):
        current_char: str | None = char
        if not case_sensitive and current_char is not None:
            current_char = current_char.lower()
        if current_char is None:
            continue
        if current_char in seen_chars:
            return False
        seen_chars.add(current_char)
    return True

def _internal_helper(s: str, start_index: int | None = 0, end_index: int | None = None) -> str | None:
    if s is None:
        return None
    if start_index is None:
        start_index = 0
    if end_index is None:
        end_index = len(s)
    return s[start_index:end_index] if start_index < end_index else ""

def another_check(text: str, ignore_spaces: bool | None = False) -> bool:
    processed_text: str | None = text
    if ignore_spaces and processed_text is not None:
        processed_text = processed_text.replace(" ", "")
    return has_all_unique_chars(processed_text or "")

