import datetime

def days_since(year: int, month: int, day: int, today: datetime.date | None = None) -> int | None:
    """
    Calculates the number of full days passed since a given date until today.
    """
    try:
        past_date: datetime.date | None = datetime.date(year, month, day)
    except ValueError:
        return None

    current_date: datetime.date = today if today is not None else datetime.date.today()

    if past_date > current_date:
        return None

    time_difference: datetime.timedelta | None = current_date - past_date
    if time_difference is None:
        return None

    return time_difference.days

def days_until_next_month(year: int, month: int, day: int | None = None) -> int | None:
    """
    Calculates days remaining until the start of the next month from a given date.
    """
    if day is None:
        day = 1

    try:
        current_date: datetime.date | None = datetime.date(year, month, day)
    except ValueError:
        return None

    if month == 12:
        next_month_date: datetime.date | None = datetime.date(year + 1, 1, 1)
    else:
        next_month_date = datetime.date(year, month + 1, 1)

    if next_month_date is None or current_date is None:
        return None

    time_diff: datetime.timedelta | None = next_month_date - current_date
    if time_diff is None:
        return None

    return time_diff.days

