class ToDoList:
    def __init__(self) -> None:
        self.tasks: dict[str, bool] = {}

    def add_task(self, task_name: str, initial_status: bool | None = False) -> None:
        self.tasks[task_name] = initial_status

    def mark_completed(self, task_name: str, success: bool | None = True) -> bool:
        if task_name in self.tasks:
            self.tasks[task_name] = success
            return True
        return False

    def get_pending_tasks(self, sort_alpha: bool | None = False) -> list[str]:
        pending: list[str] = [name for name, completed in self.tasks.items() if not completed]
        if sort_alpha:
            pending.sort()
        return pending

    def remove_task(self, task_name: str, silent_fail: bool | None = False) -> bool | None:
        if task_name in self.tasks:
            del self.tasks[task_name]
            return True
        return None if silent_fail else False

    def get_all_tasks(self, include_completed: bool | None = True) -> list[str]:
        if include_completed:
            return list(self.tasks.keys())
        else:
            return self.get_pending_tasks()

