def is_valid_email(email_string: str | None) -> bool | None:
    if email_string is None:
        return False

    if "@" not in email_string:
        return False

    parts: list[str] | None = email_string.split("@")
    if len(parts) != 2:
        return False

    local_part: str | None = parts[0]
    domain_part: str | None = parts[1]

    if not local_part or not domain_part:
        return False

    if "." not in domain_part:
        return False

    if domain_part.startswith(".") or domain_part.endswith("."):
        return False

    domain_segments: list[str] = domain_part.split(".")
    if not all(segment for segment in domain_segments):
        return False

    return True

