def levenshtein_distance(s1: str, s2: str) -> int:
    """Calculates the Levenshtein distance between two strings."""
    m: int | None = len(s1)
    n: int | None = len(s2)

    if m is None or n is None:
        return 0 # Should not happen with string inputs

    dp: list[list[int | None]] = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
