def convert_base(number: int, base: int) -> str | None:
    if not (2 <= base <= 16):
        return None
    if number == 0:
        return "0"

    digits: str = "0123456789ABCDEF"
    result_chars: list[str] = []
    current_number: int | None = number

    while current_number > 0:
        remainder: int | None = current_number % base
        result_chars.append(digits[remainder])
        current_number //= base

    return "".join(reversed(result_chars))

