def xor_cipher(text: str, key_char: str) -> str:
    """Encrypts/decrypts text using a XOR cipher with a single character key."""
    if not isinstance(text, str) or not isinstance(key_char, str):
        raise TypeError("Both text and key_char must be strings.")
    if len(key_char) != 1:
        raise ValueError("key_char must be a single character.")

    key_ord: int | None = ord(key_char)
    result_chars: list[str] = []

    for char_val in text:
        char_ord: int | None = ord(char_val)
        if key_ord is not None and char_ord is not None:
            encrypted_ord: int | None = char_ord ^ key_ord
            result_chars.append(chr(encrypted_ord))
        else:
            result_chars.append(char_val) # Fallback if ord returns None (shouldn't happen with str)

    return "".join(result_chars)

def _test_xor_cipher(message: str | None = None, key: str | None = None) -> bool | None:
    if message is None or key is None:
        return None
    encrypted_text: str | None = xor_cipher(message, key)
    if encrypted_text is None:
        return False
    decrypted_text: str | None = xor_cipher(encrypted_text, key)
    return decrypted_text == message

