import re

def is_palindrome_string(s: str | None = None) -> bool:
    if s is None:
        return False

    sanitized_s: str | None = re.sub(r'[^a-zA-Z0-9]', '', s).lower()

    if sanitized_s is None:
        return False

    left: int | None = 0
    right: int | None = len(sanitized_s) - 1

    while left is not None and right is not None and left < right:
        if sanitized_s[left] != sanitized_s[right]:
            return False
        left += 1
        right -= 1

    return True

