def convert_temperature(value: float, unit_from: str, unit_to: str, precision: int | None = None) -> float:
    """Converts a temperature value from one unit to another."""

    kelvin_value: float | None = None
    if unit_from == 'C':
        kelvin_value = value + 273.15
    elif unit_from == 'F':
        kelvin_value = (value - 32) * 5/9 + 273.15
    elif unit_from == 'K':
        kelvin_value = value

    result: float | None = None
    if unit_to == 'C':
        result = kelvin_value - 273.15 if kelvin_value is not None else None
    elif unit_to == 'F':
        result = (kelvin_value - 273.15) * 9/5 + 32 if kelvin_value is not None else None
    elif unit_to == 'K':
        result = kelvin_value

    if result is None:
        raise ValueError("Conversion failed, perhaps an invalid unit was provided.")

    if precision is not None:
        return round(result, precision)

    return result

def main(initial_value: float | None = 0.0, from_unit: str | None = 'C', to_unit: str | None = 'F') -> None:
    if initial_value is not None and from_unit is not None and to_unit is not None:
        converted = convert_temperature(initial_value, from_unit, to_unit, precision=2)
        print(f"{initial_value}{from_unit} is {converted}{to_unit}")
    else:
        print("Missing input for conversion.")

