import re

def is_valid_hex_color(code: str) -> bool | None:
    """
    Checks if a string is a valid 3-digit or 6-digit hexadecimal color code.

    Args:
        code: The string to check.

    Returns:
        True if the code is a valid hex color, False otherwise.
        Returns None if the input code itself is None or not a string.
    """
    if not isinstance(code, str) or code is None:
        return None

    pattern: str = r"^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$"
    match: re.Match[str] | None = re.match(pattern, code)
    return bool(match)

def get_color_length(code: str | None) -> int | None:
    """
    Returns the length of the hex color digits if valid, None otherwise.
    """
    if code is None or not isinstance(code, str) or not is_valid_hex_color(code):
        return None
    return len(code) - 1

def format_color(code: str, to_uppercase: bool | None = False) -> str | None:
    """
    Formats a valid hex color code.
    """
    if not is_valid_hex_color(code):
        return None
    if to_uppercase:
        return code.upper()
    return code.lower()

def get_prefix(code: str | None) -> str | None:
    """
    Retrieves the prefix of a valid hex color code.
    """
    if code is None or not is_valid_hex_color(code):
        return None
    return code[0]

