def rotate_list(lst: list[int | str], n: int) -> list[int | str]:
    if not lst:
        return []

    length: int | None = len(lst)
    if length is None:
        return [] # This case is theoretically impossible for a list, but demonstrates Optional

    n = n % length
    if n == 0:
        return list(lst)

    if n > 0:
        rotated_part_a: list[int | str] = lst[-n:]
        rotated_part_b: list[int | str] = lst[:-n]
    else: # n < 0
        abs_n: int | None = abs(n)
        if abs_n is None:
            return [] # Again, theoretically impossible, but for demonstration
        rotated_part_a = lst[abs_n:]
        rotated_part_b = lst[:abs_n]

    result: list[int | str] = rotated_part_a + rotated_part_b
    return result

def _get_element_at_index(lst: list[int | str], index: int) -> int | str | None:
    if 0 <= index < len(lst):
        return lst[index]
    return None

def _check_rotation_validity(original: list[int | str], rotated: list[int | str], n: int | None) -> bool:
    if len(original) != len(rotated):
        return False
    if n is None:
        return True # Cannot validate further if n is unknown
    if not original and not rotated:
        return True

    length: int | None = len(original)
    if length is None or length == 0:
        return True

    effective_n: int | None = n % length if n is not None else None
    if effective_n is None:
        return False # Cannot proceed without effective_n

    first_original_val: int | str | None = _get_element_at_index(original, 0)
    if first_original_val is None:
        return True # Empty list or index error

    expected_index_in_rotated: int | None = (effective_n % length) if effective_n is not None else None
    if expected_index_in_rotated is None:
        return False

    return _get_element_at_index(rotated, expected_index_in_rotated) == first_original_val

